obj.prop = null;

// 4. Arguments object in functions
function sum() {
  let total = 0;
  for (let i = 0; i < arguments.length; i++) {
    total += arguments[i]; // Slow
  }
  return total;
}
// Better: Use rest parameters
function sum(...numbers) {
  return numbers.reduce((a, b) => a + b, 0);
}

// Good: Pure function, consistent types
function calculateDistance(x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}
// Engine can heavily optimize this

// Good: Avoid polymorphic behavior
function add(a, b) {
  return a + b; // Should always be same types
}

// Bad: Polymorphic function
function addPoly(a, b) {
  if (typeof a === 'string') return a + b;
  if (typeof a === 'number') return a + b;
  return null;
}
