// Better: Reuse object structure
function processItemsOptimized(items) {
  const results = [];
  for (const item of items) {
    results.push({ processed: item.value * 2 });
  }
  return results;
}

// Even Better: Use typed arrays for numeric data
function processNumbers(numbers) {
  const results = new Float64Array(numbers.length);
  for (let i = 0; i < numbers.length; i++) {
    results[i] = numbers[i] * 2;
  }
  return results;
}
